124	// handleAuthStart generates a CSRF state token, stores it in the session, and
125	// redirects the browser to the IdP's authorization endpoint.
126	func (d *Deps) handleAuthStart(c *gin.Context) {
127		providerName := c.Param("provider")
128		provider, ok := d.Providers[providerName]
129		if !ok {
130			c.JSON(http.StatusBadRequest, gin.H{"error": "unknown provider"})
131			return
132		}
133	
134		state, err := generateState()
135		if err != nil {
136			log.Printf("auth start: generate state: %v", err)
137			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
138			return
139		}
140	
141		d.Sessions.SetOAuthState(c.Request.Context(), state)
142	
143		url := provider.AuthCodeURL(state)
144		c.Redirect(http.StatusTemporaryRedirect, url)
145	}
146	
147	// handleAuthCallback exchanges the authorization code, upserts the user +
148	// auth_identity, consumes any matching invitation, sets the session cookie, and
149	// redirects to the frontend.
150	func (d *Deps) handleAuthCallback(c *gin.Context) {
151		providerName := c.Param("provider")
152		provider, ok := d.Providers[providerName]
153		if !ok {
154			c.JSON(http.StatusBadRequest, gin.H{"error": "unknown provider"})
155			return
156		}
157	
158		ctx := c.Request.Context()
159	
160		// Verify CSRF state.
161		expectedState := d.Sessions.ConsumeOAuthState(ctx)
162		if expectedState == "" || c.Query("state") != expectedState {
163			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid state"})
164			return
165		}
166	
167		code := c.Query("code")
168		if code == "" {
169			c.JSON(http.StatusBadRequest, gin.H{"error": "missing code"})
170			return
171		}
172	
173		// Exchange code for token.
174		token, err := provider.Exchange(ctx, code)
175		if err != nil {
176			log.Printf("auth callback (%s): exchange: %v", providerName, err)
177			c.JSON(http.StatusBadGateway, gin.H{"error": "token exchange failed"})
178			return
179		}
180	
181		// Fetch user info from IdP.
182		info, err := provider.FetchUserInfo(ctx, token)
183		if err != nil {
184			log.Printf("auth callback (%s): userinfo: %v", providerName, err)
185			c.JSON(http.StatusBadGateway, gin.H{"error": "userinfo fetch failed"})
186			return
187		}
188	
189		// Upsert user + auth_identity and consume invitations inside a single transaction.
190		userID, err := d.upsertIdentityAndConsumeInvitations(ctx, provider.Name(), info)
191		if err != nil {
192			log.Printf("auth callback (%s): upsert identity: %v", providerName, err)
193			c.JSON(http.StatusInternalServerError, gin.H{"error": "identity upsert failed"})
194			return
195		}
196	
197		// Set session.
198		d.Sessions.SetUserID(ctx, userID)
199	
200		c.Redirect(http.StatusTemporaryRedirect, d.Cfg.FrontendBaseURL)
201	}
202	
203	// upsertIdentityAndConsumeInvitations runs inside a user_db transaction:
204	//  1. Find existing auth_identity by (provider, sub); if found, return its user_id.
205	//  2. Otherwise create/upsert user row and link auth_identity.
206	//  3. Check PLATFORM_ADMIN_EMAILS; if the verified email matches, ensure platform_admin membership.
207	//  4. Find and atomically accept any pending invitations for this email.
208	func (d *Deps) upsertIdentityAndConsumeInvitations(ctx context.Context, providerName string, info *oauth.UserInfo) (uuid.UUID, error) {
209		var userID uuid.UUID
210	
211		err := pgxTx(ctx, d.DB, func(tx pgx.Tx) error {
212			// Check for existing identity.
213			ai, err := d.Users.FindByProviderSub(ctx, providerName, info.ProviderSub)
214			if err != nil && !errors.Is(err, pgx.ErrNoRows) {
215				return fmt.Errorf("find identity: %w", err)
216			}
217	
218			if ai != nil {
219				// Returning user — update profile.
220				userID = ai.UserID
221				if _, err := d.Users.UpdateProfile(ctx, userID, info.DisplayName, info.AvatarURL); err != nil {
222					return fmt.Errorf("update profile: %w", err)
223				}
224			} else {
225				// New identity — create or match user by email.
226				u, err := d.Users.EnsureUser(ctx, info.Email, info.DisplayName, info.AvatarURL)
227				if err != nil {
228					return fmt.Errorf("ensure user: %w", err)
229				}
230				userID = u.ID
231				if _, err := d.Users.LinkAuthIdentity(ctx, userID, providerName, info.ProviderSub, info.Email, info.EmailVerified); err != nil {
232					return fmt.Errorf("link identity: %w", err)
233				}
234			}
235	
236			// PLATFORM_ADMIN_EMAILS check (only for verified emails).
237			if info.EmailVerified && d.isPlatformAdmin(info.Email) {
238				if err := d.ensurePlatformAdmin(ctx, userID); err != nil {
239					return fmt.Errorf("platform admin: %w", err)
240				}
241			}
242	
243			// Consume pending invitations for this email.
244			if info.Email != "" {
245				invitations, err := d.Orgs.FindPendingInvitationsByEmail(ctx, info.Email)
246				if err != nil {
247					return fmt.Errorf("find invitations: %w", err)
248				}
249				for _, inv := range invitations {
250					if err := organizations.AcceptInvitation(ctx, tx, inv, userID); err != nil {
251						return fmt.Errorf("accept invitation %s: %w", inv.ID, err)
252					}
253				}
254			}
255	
256			return nil
257		})
258		if err != nil {
259			return uuid.Nil, err
260		}
261		return userID, nil
262	}
263	
264	// isPlatformAdmin checks whether the email is in the PLATFORM_ADMIN_EMAILS list.
265	func (d *Deps) isPlatformAdmin(email string) bool {
266		for _, e := range d.Cfg.PlatformAdminEmails {
267			if strings.EqualFold(e, email) {
268				return true
269			}
270		}
271		return false
272	}
273	
274	// ensurePlatformAdmin ensures the user has a platform_admin membership on the
275	// Kitelabs organization. If the org does not exist yet (T6 seed not run), this
276	// is a no-op; the auto-grant fires again on the user's next login after the seed runs.
277	func (d *Deps) ensurePlatformAdmin(ctx context.Context, userID uuid.UUID) error {
278		org, err := d.Orgs.FindOrganizationBySlug(ctx, "kitelabs")
279		if err != nil {
280			if errors.Is(err, pgx.ErrNoRows) {
281				return nil
282			}
283			return err
284		}
285		_, err = d.Orgs.EnsureMembership(ctx, userID, org.ID, "platform_admin")
286		return err
287	}
288	
289	// handleLogout destroys the session and clears the cookie.
290	func (d *Deps) handleLogout(c *gin.Context) {
291		if err := d.Sessions.Destroy(c.Request.Context()); err != nil {
292			log.Printf("logout: destroy session: %v", err)
293		}
294		c.Status(http.StatusNoContent)
295	}
