297	// meResponse is the JSON body returned by GET /api/me.
298	type meResponse struct {
299		User                   meUser       `json:"user"`
300		Memberships            []meMembship `json:"memberships"`
301		AccessibleWorkspaceIDs []string     `json:"accessible_workspace_ids"`
302	}
303	
304	type meUser struct {
305		ID          string `json:"id"`
306		Email       string `json:"email"`
307		DisplayName string `json:"display_name"`
308		AvatarURL   string `json:"avatar_url"`
309	}
310	
311	type meMembship struct {
312		OrganizationID string `json:"organization_id"`
313		Role           string `json:"role"`
314	}
315	
316	// handleMe returns the current user's profile, memberships, and accessible workspace IDs.
317	func (d *Deps) handleMe(c *gin.Context) {
318		ctx := c.Request.Context()
319		userID := d.Sessions.GetUserID(ctx)
320		if userID == uuid.Nil {
321			c.JSON(http.StatusUnauthorized, gin.H{"error": "not authenticated"})
322			return
323		}
324	
325		u, err := d.Users.FindByID(ctx, userID)
326		if err != nil {
327			if errors.Is(err, pgx.ErrNoRows) {
328				c.JSON(http.StatusUnauthorized, gin.H{"error": "user not found"})
329				return
330			}
331			log.Printf("/api/me: find user: %v", err)
332			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
333			return
334		}
335	
336		memberships, err := d.Orgs.MembershipsByUser(ctx, userID)
337		if err != nil {
338			log.Printf("/api/me: memberships: %v", err)
339			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
340			return
341		}
342	
343		wsIDs, err := d.Orgs.AccessibleWorkspaceIDs(ctx, userID)
344		if err != nil {
345			log.Printf("/api/me: accessible workspace IDs: %v", err)
346			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
347			return
348		}
349	
350		wsIDStrings := make([]string, len(wsIDs))
351		for i, id := range wsIDs {
352			wsIDStrings[i] = id.String()
353		}
354	
355		meMembs := make([]meMembship, len(memberships))
356		for i, m := range memberships {
357			meMembs[i] = meMembship{
358				OrganizationID: m.OrganizationID.String(),
359				Role:           m.Role,
360			}
361		}
362	
363		c.JSON(http.StatusOK, meResponse{
364			User: meUser{
365				ID:          u.ID.String(),
366				Email:       u.Email,
367				DisplayName: u.DisplayName,
368				AvatarURL:   u.AvatarURL,
369			},
370			Memberships:            meMembs,
371			AccessibleWorkspaceIDs: wsIDStrings,
372		})
373	}
374	
375	// validateSessionRequest is the body of POST /internal/sessions/validate.
376	type validateSessionRequest struct {
377		CookieValue string `json:"cookie_value" binding:"required"`
378	}
379	
380	// validateSessionResponse is returned on a successful session validation.
381	type validateSessionResponse struct {
382		UserID                 string   `json:"user_id"`
383		AccessibleWorkspaceIDs []string `json:"accessible_workspace_ids"`
384	}
385	
386	// handleValidateSession validates a session cookie and returns the user_id and
387	// accessible_workspace_ids. Called by workflow-backend's RequireAuth middleware.
388	func (d *Deps) handleValidateSession(c *gin.Context) {
389		var req validateSessionRequest
390		if err := c.ShouldBindJSON(&req); err != nil {
391			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
392			return
393		}
394	
395		ctx := c.Request.Context()
396	
397		// Look up the session by token directly in the sessions table.
398		var data []byte
399		err := d.DB.QueryRow(ctx, `
400			SELECT data FROM sessions WHERE token = $1 AND expiry > now()`,
401			req.CookieValue,
402		).Scan(&data)
403		if err != nil {
404			if errors.Is(err, pgx.ErrNoRows) {
405				c.JSON(http.StatusUnauthorized, gin.H{"error": "session not found or expired"})
406				return
407			}
408			log.Printf("/internal/sessions/validate: %v", err)
409			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
410			return
411		}
412	
413		// Decode the scs gob-encoded session to extract user_id.
414		userID, err := extractUserIDFromSessionData(data)
415		if err != nil {
416			log.Printf("/internal/sessions/validate: decode session: %v", err)
417			c.JSON(http.StatusUnauthorized, gin.H{"error": "invalid session data"})
418			return
419		}
420		if userID == uuid.Nil {
421			c.JSON(http.StatusUnauthorized, gin.H{"error": "no user in session"})
422			return
423		}
424	
425		wsIDs, err := d.Orgs.AccessibleWorkspaceIDs(ctx, userID)
426		if err != nil {
427			log.Printf("/internal/sessions/validate: accessible workspace IDs: %v", err)
428			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
429			return
430		}
431	
432		wsIDStrings := make([]string, len(wsIDs))
433		for i, id := range wsIDs {
434			wsIDStrings[i] = id.String()
435		}
436	
437		c.JSON(http.StatusOK, validateSessionResponse{
438			UserID:                 userID.String(),
439			AccessibleWorkspaceIDs: wsIDStrings,
440		})
441	}
442	
443	// generateState produces a cryptographically random OAuth CSRF state token.
444	func generateState() (string, error) {
445		b := make([]byte, 32)
446		if _, err := rand.Read(b); err != nil {
447			return "", err
448		}
449		return base64.URLEncoding.EncodeToString(b), nil
450	}
451	
452	// pgxTx runs fn inside a pgx transaction; rolls back on error.
453	func pgxTx(ctx context.Context, pool *pgxpool.Pool, fn func(pgx.Tx) error) error {
454		tx, err := pool.Begin(ctx)
455		if err != nil {
456			return err
457		}
458		defer func() { _ = tx.Rollback(ctx) }()
459		if err := fn(tx); err != nil {
460			return err
461		}
462		return tx.Commit(ctx)
463	}
