// Package httpapi wires together all HTTP routes for user-service.
package httpapi

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/base64"
	"errors"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/alexedwards/scs/v2"
	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/tiendv89/user-service/internal/config"
	"github.com/tiendv89/user-service/internal/oauth"
	"github.com/tiendv89/user-service/internal/organizations"
	"github.com/tiendv89/user-service/internal/serviceauth"
	"github.com/tiendv89/user-service/internal/sessions"
	"github.com/tiendv89/user-service/internal/users"
)

// Deps holds the shared dependencies wired into every handler.
type Deps struct {
	Cfg       *config.Config
	DB        *pgxpool.Pool
	StdDB     *sql.DB
	Sessions  *sessions.Manager
	Providers map[string]oauth.Provider
	Users     *users.Store
	Orgs      *organizations.Store
}

// New returns a configured Gin engine with only the healthz route (no DB deps).
// Used by unit tests that do not need a real database.
func New() *gin.Engine {
	r := gin.New()
	r.Use(gin.Recovery())
	r.Use(gin.Logger())

	r.GET("/healthz", func(c *gin.Context) {
		c.Status(http.StatusNoContent)
	})

	return r
}

// NewWithDeps returns a configured Gin engine with all routes wired to real deps.
func NewWithDeps(deps *Deps) *gin.Engine {
	r := gin.New()
	r.Use(gin.Recovery())
	r.Use(gin.Logger())

	// Session middleware: load session from store before the handler, save after.
	sm := deps.Sessions.SessionManager()
	r.Use(scsGinMiddleware(sm))

	r.GET("/healthz", func(c *gin.Context) {
		c.Status(http.StatusNoContent)
	})

	// Public OAuth routes.
	r.GET("/auth/:provider/start", deps.handleAuthStart)
	r.GET("/auth/:provider/callback", deps.handleAuthCallback)
	r.POST("/auth/logout", deps.handleLogout)

	// Public user API.
	r.GET("/api/me", deps.handleMe)

	// Internal service routes (Bearer token required).
	internal := r.Group("/internal")
	internal.Use(serviceauth.RequireServiceToken(deps.Cfg.UserServiceToken))
	internal.POST("/sessions/validate", deps.handleValidateSession)

	return r
}

// scsGinMiddleware integrates scs session management into Gin by using the
// lower-level Load/Commit/WriteSessionCookie API rather than LoadAndSave, which
// wraps the ResponseWriter in a way that conflicts with Gin's own wrapper.
func scsGinMiddleware(sm *scs.SessionManager) gin.HandlerFunc {
	return func(c *gin.Context) {
		// Extract the session token from the cookie.
		var token string
		if cookie, err := c.Request.Cookie(sm.Cookie.Name); err == nil {
			token = cookie.Value
		}

		// Load session data into a new context.
		ctx, err := sm.Load(c.Request.Context(), token)
		if err != nil {
			log.Printf("session load: %v", err)
			c.AbortWithStatus(http.StatusInternalServerError)
			return
		}

		// Replace the request's context so handlers see the session.
		c.Request = c.Request.WithContext(ctx)

		// Process the request.
		c.Next()

		// After the handler chain, commit session changes and set the cookie.
		switch sm.Status(ctx) {
		case scs.Modified:
			sessionToken, expiry, commitErr := sm.Commit(ctx)
			if commitErr != nil {
				log.Printf("session commit: %v", commitErr)
				return
			}
			sm.WriteSessionCookie(ctx, c.Writer, sessionToken, expiry)
		case scs.Destroyed:
			sm.WriteSessionCookie(ctx, c.Writer, "", zeroTime)
		}
	}
}

// handleAuthStart generates a CSRF state token, stores it in the session, and
// redirects the browser to the IdP's authorization endpoint.
func (d *Deps) handleAuthStart(c *gin.Context) {
	providerName := c.Param("provider")
	provider, ok := d.Providers[providerName]
	if !ok {
		c.JSON(http.StatusBadRequest, gin.H{"error": "unknown provider"})
		return
	}

	state, err := generateState()
	if err != nil {
		log.Printf("auth start: generate state: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	d.Sessions.SetOAuthState(c.Request.Context(), state)

	url := provider.AuthCodeURL(state)
	c.Redirect(http.StatusTemporaryRedirect, url)
}

// handleAuthCallback exchanges the authorization code, upserts the user +
// auth_identity, consumes any matching invitation, sets the session cookie, and
// redirects to the frontend.
func (d *Deps) handleAuthCallback(c *gin.Context) {
	providerName := c.Param("provider")
	provider, ok := d.Providers[providerName]
	if !ok {
		c.JSON(http.StatusBadRequest, gin.H{"error": "unknown provider"})
		return
	}

	ctx := c.Request.Context()

	// Verify CSRF state.
	expectedState := d.Sessions.ConsumeOAuthState(ctx)
	if expectedState == "" || c.Query("state") != expectedState {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid state"})
		return
	}

	code := c.Query("code")
	if code == "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": "missing code"})
		return
	}

	// Exchange code for token.
	token, err := provider.Exchange(ctx, code)
	if err != nil {
		log.Printf("auth callback (%s): exchange: %v", providerName, err)
		c.JSON(http.StatusBadGateway, gin.H{"error": "token exchange failed"})
		return
	}

	// Fetch user info from IdP.
	info, err := provider.FetchUserInfo(ctx, token)
	if err != nil {
		log.Printf("auth callback (%s): userinfo: %v", providerName, err)
		c.JSON(http.StatusBadGateway, gin.H{"error": "userinfo fetch failed"})
		return
	}

	// Upsert user + auth_identity and consume invitations inside a single transaction.
	userID, err := d.upsertIdentityAndConsumeInvitations(ctx, provider.Name(), info)
	if err != nil {
		log.Printf("auth callback (%s): upsert identity: %v", providerName, err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "identity upsert failed"})
		return
	}

	// Set session.
	d.Sessions.SetUserID(ctx, userID)

	c.Redirect(http.StatusTemporaryRedirect, d.Cfg.FrontendBaseURL)
}

// upsertIdentityAndConsumeInvitations runs inside a user_db transaction:
//  1. Find existing auth_identity by (provider, sub); if found, return its user_id.
//  2. Otherwise create/upsert user row and link auth_identity.
//  3. Check PLATFORM_ADMIN_EMAILS; if the verified email matches, ensure platform_admin membership.
//  4. Find and atomically accept any pending invitations for this email.
func (d *Deps) upsertIdentityAndConsumeInvitations(ctx context.Context, providerName string, info *oauth.UserInfo) (uuid.UUID, error) {
	var userID uuid.UUID

	err := pgxTx(ctx, d.DB, func(tx pgx.Tx) error {
		// Check for existing identity.
		ai, err := d.Users.FindByProviderSub(ctx, providerName, info.ProviderSub)
		if err != nil && !errors.Is(err, pgx.ErrNoRows) {
			return fmt.Errorf("find identity: %w", err)
		}

		if ai != nil {
			// Returning user — update profile.
			userID = ai.UserID
			if _, err := d.Users.UpdateProfile(ctx, userID, info.DisplayName, info.AvatarURL); err != nil {
				return fmt.Errorf("update profile: %w", err)
			}
		} else {
			// New identity — create or match user by email.
			u, err := d.Users.EnsureUser(ctx, info.Email, info.DisplayName, info.AvatarURL)
			if err != nil {
				return fmt.Errorf("ensure user: %w", err)
			}
			userID = u.ID
			if _, err := d.Users.LinkAuthIdentity(ctx, userID, providerName, info.ProviderSub, info.Email, info.EmailVerified); err != nil {
				return fmt.Errorf("link identity: %w", err)
			}
		}

		// PLATFORM_ADMIN_EMAILS check (only for verified emails).
		if info.EmailVerified && d.isPlatformAdmin(info.Email) {
			if err := d.ensurePlatformAdmin(ctx, userID); err != nil {
				return fmt.Errorf("platform admin: %w", err)
			}
		}

		// Consume pending invitations for this email.
		if info.Email != "" {
			invitations, err := d.Orgs.FindPendingInvitationsByEmail(ctx, info.Email)
			if err != nil {
				return fmt.Errorf("find invitations: %w", err)
			}
			for _, inv := range invitations {
				if err := organizations.AcceptInvitation(ctx, tx, inv, userID); err != nil {
					return fmt.Errorf("accept invitation %s: %w", inv.ID, err)
				}
			}
		}

		return nil
	})
	if err != nil {
		return uuid.Nil, err
	}
	return userID, nil
}

// isPlatformAdmin checks whether the email is in the PLATFORM_ADMIN_EMAILS list.
func (d *Deps) isPlatformAdmin(email string) bool {
	for _, e := range d.Cfg.PlatformAdminEmails {
		if strings.EqualFold(e, email) {
			return true
		}
	}
	return false
}

// ensurePlatformAdmin ensures the user has a platform_admin membership on the
// Kitelabs organization. If the org does not exist yet (T6 seed not run), this
// is a no-op; the auto-grant fires again on the user's next login after the seed runs.
func (d *Deps) ensurePlatformAdmin(ctx context.Context, userID uuid.UUID) error {
	org, err := d.Orgs.FindOrganizationBySlug(ctx, "kitelabs")
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil
		}
		return err
	}
	_, err = d.Orgs.EnsureMembership(ctx, userID, org.ID, "platform_admin")
	return err
}

// handleLogout destroys the session and clears the cookie.
func (d *Deps) handleLogout(c *gin.Context) {
	if err := d.Sessions.Destroy(c.Request.Context()); err != nil {
		log.Printf("logout: destroy session: %v", err)
	}
	c.Status(http.StatusNoContent)
}

// meResponse is the JSON body returned by GET /api/me.
type meResponse struct {
	User                   meUser       `json:"user"`
	Memberships            []meMembship `json:"memberships"`
	AccessibleWorkspaceIDs []string     `json:"accessible_workspace_ids"`
}

type meUser struct {
	ID          string `json:"id"`
	Email       string `json:"email"`
	DisplayName string `json:"display_name"`
	AvatarURL   string `json:"avatar_url"`
}

type meMembship struct {
	OrganizationID string `json:"organization_id"`
	Role           string `json:"role"`
}

// handleMe returns the current user's profile, memberships, and accessible workspace IDs.
func (d *Deps) handleMe(c *gin.Context) {
	ctx := c.Request.Context()
	userID := d.Sessions.GetUserID(ctx)
	if userID == uuid.Nil {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "not authenticated"})
		return
	}

	u, err := d.Users.FindByID(ctx, userID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "user not found"})
			return
		}
		log.Printf("/api/me: find user: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	memberships, err := d.Orgs.MembershipsByUser(ctx, userID)
	if err != nil {
		log.Printf("/api/me: memberships: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	wsIDs, err := d.Orgs.AccessibleWorkspaceIDs(ctx, userID)
	if err != nil {
		log.Printf("/api/me: accessible workspace IDs: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	wsIDStrings := make([]string, len(wsIDs))
	for i, id := range wsIDs {
		wsIDStrings[i] = id.String()
	}

	meMembs := make([]meMembship, len(memberships))
	for i, m := range memberships {
		meMembs[i] = meMembship{
			OrganizationID: m.OrganizationID.String(),
			Role:           m.Role,
		}
	}

	c.JSON(http.StatusOK, meResponse{
		User: meUser{
			ID:          u.ID.String(),
			Email:       u.Email,
			DisplayName: u.DisplayName,
			AvatarURL:   u.AvatarURL,
		},
		Memberships:            meMembs,
		AccessibleWorkspaceIDs: wsIDStrings,
	})
}

// validateSessionRequest is the body of POST /internal/sessions/validate.
type validateSessionRequest struct {
	CookieValue string `json:"cookie_value" binding:"required"`
}

// validateSessionResponse is returned on a successful session validation.
type validateSessionResponse struct {
	UserID                 string   `json:"user_id"`
	AccessibleWorkspaceIDs []string `json:"accessible_workspace_ids"`
}

// handleValidateSession validates a session cookie and returns the user_id and
// accessible_workspace_ids. Called by workflow-backend's RequireAuth middleware.
func (d *Deps) handleValidateSession(c *gin.Context) {
	var req validateSessionRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	ctx := c.Request.Context()

	// Look up the session by token directly in the sessions table.
	var data []byte
	err := d.DB.QueryRow(ctx, `
		SELECT data FROM sessions WHERE token = $1 AND expiry > now()`,
		req.CookieValue,
	).Scan(&data)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "session not found or expired"})
			return
		}
		log.Printf("/internal/sessions/validate: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	// Decode the scs gob-encoded session to extract user_id.
	userID, err := extractUserIDFromSessionData(data)
	if err != nil {
		log.Printf("/internal/sessions/validate: decode session: %v", err)
		c.JSON(http.StatusUnauthorized, gin.H{"error": "invalid session data"})
		return
	}
	if userID == uuid.Nil {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "no user in session"})
		return
	}

	wsIDs, err := d.Orgs.AccessibleWorkspaceIDs(ctx, userID)
	if err != nil {
		log.Printf("/internal/sessions/validate: accessible workspace IDs: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	wsIDStrings := make([]string, len(wsIDs))
	for i, id := range wsIDs {
		wsIDStrings[i] = id.String()
	}

	c.JSON(http.StatusOK, validateSessionResponse{
		UserID:                 userID.String(),
		AccessibleWorkspaceIDs: wsIDStrings,
	})
}

// generateState produces a cryptographically random OAuth CSRF state token.
func generateState() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return base64.URLEncoding.EncodeToString(b), nil
}

// pgxTx runs fn inside a pgx transaction; rolls back on error.
func pgxTx(ctx context.Context, pool *pgxpool.Pool, fn func(pgx.Tx) error) error {
	tx, err := pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	if err := fn(tx); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

package httpapi

import (
	"bytes"
	"encoding/gob"
	"fmt"
	"time"

	"github.com/google/uuid"
)

// scsPayload mirrors the internal struct that scs/GobCodec uses to encode
// session data.  The data column in the sessions table contains a gob-encoded
// value of exactly this shape.
type scsPayload struct {
	Deadline time.Time
	Values   map[string]interface{}
}

// extractUserIDFromSessionData decodes the gob payload written by scs and
// returns the "user_id" value. Returns uuid.Nil if the key is absent.
func extractUserIDFromSessionData(data []byte) (uuid.UUID, error) {
	// scs stores string values as plain strings; register string so gob can
	// decode map[string]interface{} entries.
	gob.Register("")

	var payload scsPayload
	if err := gob.NewDecoder(bytes.NewReader(data)).Decode(&payload); err != nil {
		return uuid.Nil, fmt.Errorf("decode session gob: %w", err)
	}

	raw, ok := payload.Values["user_id"]
	if !ok {
		return uuid.Nil, nil
	}
	str, ok := raw.(string)
	if !ok {
		return uuid.Nil, fmt.Errorf("user_id is not a string: %T", raw)
	}
	id, err := uuid.Parse(str)
	if err != nil {
		return uuid.Nil, fmt.Errorf("parse user_id UUID: %w", err)
	}
	return id, nil
}

// Package users provides CRUD for the users and auth_identities tables.
package users

import (
	"context"
	"errors"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// User represents a platform user.
type User struct {
	ID          uuid.UUID
	Email       string
	DisplayName string
	AvatarURL   string
	CreatedAt   time.Time
	UpdatedAt   time.Time
}

// AuthIdentity links a user to an OAuth provider identity.
type AuthIdentity struct {
	ID            uuid.UUID
	UserID        uuid.UUID
	Provider      string
	ProviderSub   string
	Email         string
	EmailVerified bool
	CreatedAt     time.Time
}

// Store performs user and auth_identity operations.
type Store struct {
	db *pgxpool.Pool
}

// New creates a new Store.
func New(db *pgxpool.Pool) *Store {
	return &Store{db: db}
}

// EnsureUser upserts a user by email. If the user already exists (matched by
// lower(email)), it returns the existing record. Otherwise it creates a new one.
// On conflict the display_name and avatar_url are updated.
func (s *Store) EnsureUser(ctx context.Context, email, displayName, avatarURL string) (*User, error) {
	row := s.db.QueryRow(ctx, `
		INSERT INTO users (email, display_name, avatar_url)
		VALUES ($1, $2, $3)
		ON CONFLICT DO NOTHING
		RETURNING id, email, display_name, avatar_url, created_at, updated_at`,
		email, displayName, avatarURL,
	)
	u, err := scanUser(row)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			// Row already existed — fetch it.
			return s.FindByEmail(ctx, email)
		}
		return nil, err
	}
	return u, nil
}

// FindByID looks up a user by primary key.
func (s *Store) FindByID(ctx context.Context, id uuid.UUID) (*User, error) {
	row := s.db.QueryRow(ctx, `
		SELECT id, email, display_name, avatar_url, created_at, updated_at
		FROM users WHERE id = $1`, id)
	return scanUser(row)
}

// FindByEmail looks up a user by email (case-insensitive).
func (s *Store) FindByEmail(ctx context.Context, email string) (*User, error) {
	row := s.db.QueryRow(ctx, `
		SELECT id, email, display_name, avatar_url, created_at, updated_at
		FROM users WHERE lower(email) = lower($1)`, email)
	return scanUser(row)
}

// UpdateProfile updates the display_name, avatar_url and updated_at for an existing user.
func (s *Store) UpdateProfile(ctx context.Context, id uuid.UUID, displayName, avatarURL string) (*User, error) {
	row := s.db.QueryRow(ctx, `
		UPDATE users SET display_name = $2, avatar_url = $3, updated_at = now()
		WHERE id = $1
		RETURNING id, email, display_name, avatar_url, created_at, updated_at`,
		id, displayName, avatarURL,
	)
	return scanUser(row)
}

// LinkAuthIdentity inserts an auth_identity row. If one already exists for
// (provider, provider_sub) it is returned unchanged.
func (s *Store) LinkAuthIdentity(ctx context.Context, userID uuid.UUID, provider, providerSub, email string, emailVerified bool) (*AuthIdentity, error) {
	row := s.db.QueryRow(ctx, `
		INSERT INTO auth_identities (user_id, provider, provider_sub, email, email_verified)
		VALUES ($1, $2, $3, $4, $5)
		ON CONFLICT (provider, provider_sub) DO NOTHING
		RETURNING id, user_id, provider, provider_sub, email, email_verified, created_at`,
		userID, provider, providerSub, email, emailVerified,
	)
	ai, err := scanAuthIdentity(row)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return s.FindByProviderSub(ctx, provider, providerSub)
		}
		return nil, err
	}
	return ai, nil
}

// FindByProviderSub looks up an auth_identity by (provider, provider_sub).
func (s *Store) FindByProviderSub(ctx context.Context, provider, providerSub string) (*AuthIdentity, error) {
	row := s.db.QueryRow(ctx, `
		SELECT id, user_id, provider, provider_sub, email, email_verified, created_at
		FROM auth_identities WHERE provider = $1 AND provider_sub = $2`,
		provider, providerSub,
	)
	ai, err := scanAuthIdentity(row)
	if err != nil {
		return nil, err
	}
	return ai, nil
}

func scanUser(row pgx.Row) (*User, error) {
	var u User
	var displayName, avatarURL *string
	err := row.Scan(&u.ID, &u.Email, &displayName, &avatarURL, &u.CreatedAt, &u.UpdatedAt)
	if err != nil {
		return nil, err
	}
	if displayName != nil {
		u.DisplayName = *displayName
	}
	if avatarURL != nil {
		u.AvatarURL = *avatarURL
	}
	return &u, nil
}

func scanAuthIdentity(row pgx.Row) (*AuthIdentity, error) {
	var ai AuthIdentity
	var email *string
	var emailVerified *bool
	err := row.Scan(&ai.ID, &ai.UserID, &ai.Provider, &ai.ProviderSub, &email, &emailVerified, &ai.CreatedAt)
	if err != nil {
		return nil, err
	}
	if email != nil {
		ai.Email = *email
	}
	if emailVerified != nil {
		ai.EmailVerified = *emailVerified
	}
	return &ai, nil
}

// Package organizations provides CRUD for organizations, memberships,
// workspace_memberships, and organization_invitations.
package organizations

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// Organization is the tenancy boundary that owns workspaces.
type Organization struct {
	ID        uuid.UUID
	Slug      string
	Name      string
	CreatedAt time.Time
	UpdatedAt time.Time
}

// Membership links a user to an organization with a role.
type Membership struct {
	ID             uuid.UUID
	UserID         uuid.UUID
	OrganizationID uuid.UUID
	Role           string
	CreatedAt      time.Time
	UpdatedAt      time.Time
}

// WorkspaceMembership scopes a user to a specific workspace.
type WorkspaceMembership struct {
	ID          uuid.UUID
	UserID      uuid.UUID
	WorkspaceID uuid.UUID
	CreatedAt   time.Time
}

// Invitation is an open invitation for a user to join an organization.
type Invitation struct {
	ID               uuid.UUID
	OrganizationID   uuid.UUID
	Email            string
	Role             string
	InvitedByUserID  *uuid.UUID
	WorkspaceIDs     []uuid.UUID
	CreatedAt        time.Time
	ExpiresAt        *time.Time
	AcceptedAt       *time.Time
	AcceptedByUserID *uuid.UUID
}

// Store performs operations on the tenancy and invitation tables.
type Store struct {
	db *pgxpool.Pool
}

// New creates a new Store.
func New(db *pgxpool.Pool) *Store {
	return &Store{db: db}
}

// FindOrganizationByID returns an organization by primary key.
func (s *Store) FindOrganizationByID(ctx context.Context, id uuid.UUID) (*Organization, error) {
	row := s.db.QueryRow(ctx, `
		SELECT id, slug, name, created_at, updated_at
		FROM organizations WHERE id = $1`, id)
	return scanOrg(row)
}

// FindOrganizationBySlug returns an organization by slug.
func (s *Store) FindOrganizationBySlug(ctx context.Context, slug string) (*Organization, error) {
	row := s.db.QueryRow(ctx, `
		SELECT id, slug, name, created_at, updated_at
		FROM organizations WHERE slug = $1`, slug)
	return scanOrg(row)
}

// CreateOrganization inserts a new organization.
func (s *Store) CreateOrganization(ctx context.Context, slug, name string) (*Organization, error) {
	row := s.db.QueryRow(ctx, `
		INSERT INTO organizations (slug, name)
		VALUES ($1, $2)
		RETURNING id, slug, name, created_at, updated_at`,
		slug, name,
	)
	return scanOrg(row)
}

// EnsureMembership upserts a membership row. If it already exists, the
// existing record is returned. Returns the membership row.
func (s *Store) EnsureMembership(ctx context.Context, userID, orgID uuid.UUID, role string) (*Membership, error) {
	row := s.db.QueryRow(ctx, `
		INSERT INTO memberships (user_id, organization_id, role)
		VALUES ($1, $2, $3)
		ON CONFLICT (user_id, organization_id) DO UPDATE SET role = EXCLUDED.role, updated_at = now()
		RETURNING id, user_id, organization_id, role, created_at, updated_at`,
		userID, orgID, role,
	)
	return scanMembership(row)
}

// MembershipsByUser returns all memberships for a user.
func (s *Store) MembershipsByUser(ctx context.Context, userID uuid.UUID) ([]*Membership, error) {
	rows, err := s.db.Query(ctx, `
		SELECT id, user_id, organization_id, role, created_at, updated_at
		FROM memberships WHERE user_id = $1`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Membership
	for rows.Next() {
		m, err := scanMembership(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, m)
	}
	return out, rows.Err()
}

// EnsureWorkspaceMembership upserts a workspace_membership row.
func (s *Store) EnsureWorkspaceMembership(ctx context.Context, userID, workspaceID uuid.UUID) error {
	_, err := s.db.Exec(ctx, `
		INSERT INTO workspace_memberships (user_id, workspace_id)
		VALUES ($1, $2)
		ON CONFLICT (user_id, workspace_id) DO NOTHING`,
		userID, workspaceID,
	)
	return err
}

// WorkspaceMembershipsByUser returns all workspace_membership rows for a user.
func (s *Store) WorkspaceMembershipsByUser(ctx context.Context, userID uuid.UUID) ([]*WorkspaceMembership, error) {
	rows, err := s.db.Query(ctx, `
		SELECT id, user_id, workspace_id, created_at
		FROM workspace_memberships WHERE user_id = $1`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*WorkspaceMembership
	for rows.Next() {
		wm, err := scanWorkspaceMembership(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, wm)
	}
	return out, rows.Err()
}

// AccessibleWorkspaceIDs returns the workspace IDs accessible by a user.
//
// Rules (Option 4A):
//   - A user with organization memberships but no workspace_membership rows has
//     access to all workspaces in those organizations.  Because user-service does not
//     own the workspace table, we cannot enumerate the full set. In that case we
//     return nil (= "all") and the caller (workflow-backend) must handle nil as
//     "unrestricted by this service".
//   - If any workspace_membership rows exist for the user, the user is scoped to
//     exactly those workspace IDs.
func (s *Store) AccessibleWorkspaceIDs(ctx context.Context, userID uuid.UUID) ([]uuid.UUID, error) {
	wms, err := s.WorkspaceMembershipsByUser(ctx, userID)
	if err != nil {
		return nil, err
	}
	if len(wms) == 0 {
		// No per-workspace scoping — org membership grants everything.
		return nil, nil
	}
	ids := make([]uuid.UUID, len(wms))
	for i, wm := range wms {
		ids[i] = wm.WorkspaceID
	}
	return ids, nil
}

// FindPendingInvitationByEmail returns the first pending (not accepted, not expired)
// invitation for the given (organizationID, email) pair. Uses lower(email) comparison.
func (s *Store) FindPendingInvitationByEmail(ctx context.Context, orgID uuid.UUID, email string) (*Invitation, error) {
	row := s.db.QueryRow(ctx, `
		SELECT id, organization_id, email, role, invited_by_user_id, workspace_ids,
		       created_at, expires_at, accepted_at, accepted_by_user_id
		FROM organization_invitations
		WHERE organization_id = $1
		  AND lower(email) = lower($2)
		  AND accepted_at IS NULL
		  AND (expires_at IS NULL OR expires_at > now())
		ORDER BY created_at DESC
		LIMIT 1`,
		orgID, email,
	)
	return scanInvitation(row)
}

// FindPendingInvitationsByEmail returns all pending invitations for an email
// across all organizations.
func (s *Store) FindPendingInvitationsByEmail(ctx context.Context, email string) ([]*Invitation, error) {
	rows, err := s.db.Query(ctx, `
		SELECT id, organization_id, email, role, invited_by_user_id, workspace_ids,
		       created_at, expires_at, accepted_at, accepted_by_user_id
		FROM organization_invitations
		WHERE lower(email) = lower($1)
		  AND accepted_at IS NULL
		  AND (expires_at IS NULL OR expires_at > now())
		ORDER BY created_at DESC`,
		email,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Invitation
	for rows.Next() {
		inv, err := scanInvitation(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, inv)
	}
	return out, rows.Err()
}

// AcceptInvitation atomically marks the invitation as accepted, creates/updates
// the membership, and optionally creates workspace_membership rows.
// It must be called inside a transaction; tx must be *pgx.Tx.
func AcceptInvitation(ctx context.Context, tx pgx.Tx, inv *Invitation, userID uuid.UUID) error {
	// Mark accepted.
	_, err := tx.Exec(ctx, `
		UPDATE organization_invitations
		SET accepted_at = now(), accepted_by_user_id = $2
		WHERE id = $1`, inv.ID, userID)
	if err != nil {
		return err
	}

	// Upsert membership.
	_, err = tx.Exec(ctx, `
		INSERT INTO memberships (user_id, organization_id, role)
		VALUES ($1, $2, $3)
		ON CONFLICT (user_id, organization_id) DO UPDATE SET role = EXCLUDED.role, updated_at = now()`,
		userID, inv.OrganizationID, inv.Role,
	)
	if err != nil {
		return err
	}

	// Upsert workspace_memberships if invitation specifies workspaces.
	for _, wsID := range inv.WorkspaceIDs {
		_, err = tx.Exec(ctx, `
			INSERT INTO workspace_memberships (user_id, workspace_id)
			VALUES ($1, $2)
			ON CONFLICT (user_id, workspace_id) DO NOTHING`,
			userID, wsID,
		)
		if err != nil {
			return err
		}
	}
	return nil
}

// CreateInvitation inserts a new invitation record.
func (s *Store) CreateInvitation(ctx context.Context, orgID uuid.UUID, email, role string, invitedBy *uuid.UUID, workspaceIDs []uuid.UUID, expiresAt *time.Time) (*Invitation, error) {
	var wsIDsJSON []byte
	if len(workspaceIDs) > 0 {
		var err error
		wsIDsJSON, err = json.Marshal(workspaceIDs)
		if err != nil {
			return nil, err
		}
	}
	row := s.db.QueryRow(ctx, `
		INSERT INTO organization_invitations
		  (organization_id, email, role, invited_by_user_id, workspace_ids, expires_at)
		VALUES ($1, $2, $3, $4, $5, $6)
		RETURNING id, organization_id, email, role, invited_by_user_id, workspace_ids,
		          created_at, expires_at, accepted_at, accepted_by_user_id`,
		orgID, email, role, invitedBy, wsIDsJSON, expiresAt,
	)
	return scanInvitation(row)
}

func scanOrg(row pgx.Row) (*Organization, error) {
	var o Organization
	err := row.Scan(&o.ID, &o.Slug, &o.Name, &o.CreatedAt, &o.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &o, nil
}

func scanMembership(row pgx.Row) (*Membership, error) {
	var m Membership
	err := row.Scan(&m.ID, &m.UserID, &m.OrganizationID, &m.Role, &m.CreatedAt, &m.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &m, nil
}

func scanWorkspaceMembership(row pgx.Row) (*WorkspaceMembership, error) {
	var wm WorkspaceMembership
	err := row.Scan(&wm.ID, &wm.UserID, &wm.WorkspaceID, &wm.CreatedAt)
	if err != nil {
		return nil, err
	}
	return &wm, nil
}

func scanInvitation(row pgx.Row) (*Invitation, error) {
	var inv Invitation
	var wsIDsJSON []byte
	err := row.Scan(
		&inv.ID, &inv.OrganizationID, &inv.Email, &inv.Role,
		&inv.InvitedByUserID, &wsIDsJSON,
		&inv.CreatedAt, &inv.ExpiresAt, &inv.AcceptedAt, &inv.AcceptedByUserID,
	)
	if err != nil {
		return nil, err
	}
	if wsIDsJSON != nil {
		if err := json.Unmarshal(wsIDsJSON, &inv.WorkspaceIDs); err != nil {
			return nil, err
		}
	}
	return &inv, nil
}

// ErrNotFound is returned when a requested resource does not exist.
var ErrNotFound = errors.New("not found")

