package httpapi

import (
	"bytes"
	"encoding/gob"
	"testing"
	"time"

	"github.com/google/uuid"
)

// encodeSessionData produces a scs-style gob payload for testing.
func encodeSessionData(t *testing.T, values map[string]interface{}) []byte {
	t.Helper()
	gob.Register("")
	payload := struct {
		Deadline time.Time
		Values   map[string]interface{}
	}{
		Deadline: time.Now().Add(24 * time.Hour),
		Values:   values,
	}
	var buf bytes.Buffer
	if err := gob.NewEncoder(&buf).Encode(&payload); err != nil {
		t.Fatalf("encode session data: %v", err)
	}
	return buf.Bytes()
}

func TestExtractUserIDFromSessionData_HappyPath(t *testing.T) {
	want := uuid.New()
	data := encodeSessionData(t, map[string]interface{}{
		"user_id": want.String(),
	})
	got, err := extractUserIDFromSessionData(data)
	if err != nil {
		t.Fatalf("extractUserIDFromSessionData: %v", err)
	}
	if got != want {
		t.Fatalf("expected %v, got %v", want, got)
	}
}

func TestExtractUserIDFromSessionData_MissingKey_ReturnsNil(t *testing.T) {
	data := encodeSessionData(t, map[string]interface{}{
		"other_key": "some_value",
	})
	got, err := extractUserIDFromSessionData(data)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != uuid.Nil {
		t.Fatalf("expected uuid.Nil, got %v", got)
	}
}

func TestExtractUserIDFromSessionData_InvalidGob_ReturnsError(t *testing.T) {
	_, err := extractUserIDFromSessionData([]byte("not gob encoded"))
	if err == nil {
		t.Fatal("expected error for invalid gob data")
	}
}

func TestExtractUserIDFromSessionData_InvalidUUID_ReturnsError(t *testing.T) {
	data := encodeSessionData(t, map[string]interface{}{
		"user_id": "not-a-uuid",
	})
	_, err := extractUserIDFromSessionData(data)
	if err == nil {
		t.Fatal("expected error for invalid UUID")
	}
}

package httpapi

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"

	"github.com/tiendv89/user-service/internal/serviceauth"
)

// TestValidateSession_MissingToken exercises the service-auth middleware
// directly (no DB needed).
func TestValidateSession_MissingToken_Returns401(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.Use(serviceauth.RequireServiceToken("correct-token"))
	r.POST("/internal/sessions/validate", func(c *gin.Context) {
		c.Status(http.StatusOK)
	})

	body, _ := json.Marshal(map[string]string{"cookie_value": "some-cookie"})
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPost, "/internal/sessions/validate", bytes.NewReader(body))
	// No Authorization header.
	r.ServeHTTP(w, req)

	if w.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 when no service token, got %d", w.Code)
	}
}

func TestValidateSession_WrongToken_Returns401(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.Use(serviceauth.RequireServiceToken("correct-token"))
	r.POST("/internal/sessions/validate", func(c *gin.Context) {
		c.Status(http.StatusOK)
	})

	body, _ := json.Marshal(map[string]string{"cookie_value": "some-cookie"})
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPost, "/internal/sessions/validate", bytes.NewReader(body))
	req.Header.Set("Authorization", "Bearer wrong-token")
	r.ServeHTTP(w, req)

	if w.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 with wrong token, got %d", w.Code)
	}
}

func TestValidateSession_ValidToken_Passes(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.Use(serviceauth.RequireServiceToken("correct-token"))
	r.POST("/internal/sessions/validate", func(c *gin.Context) {
		// Stub handler — just return 200.
		c.Status(http.StatusOK)
	})

	body, _ := json.Marshal(map[string]string{"cookie_value": "some-cookie"})
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPost, "/internal/sessions/validate", bytes.NewReader(body))
	req.Header.Set("Authorization", "Bearer correct-token")
	req.Header.Set("Content-Type", "application/json")
	r.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Fatalf("expected 200 with correct token, got %d", w.Code)
	}
}

